<?php namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\Place; use App\Models\Review; use Illuminate\Http\Request; class ReviewController extends Controller { public function index(Place $place){return ['data'=>$place->reviews()->where('status','approved')->with('user:id,name')->latest()->get()];} public function store(Request $r,Place $place){$d=$r->validate(['rating'=>'required|integer|between:1,5','comment'=>'required|string|max:2000']);$review=Review::updateOrCreate(['user_id'=>$r->user()->id,'place_id'=>$place->id],$d+['status'=>'pending']);return response()->json(['data'=>$review],201);} public function update(Request $r,Review $review){abort_unless($review->user_id===$r->user()->id,403);$review->update($r->validate(['rating'=>'required|integer|between:1,5','comment'=>'required|string|max:2000'])+['status'=>'pending']);return ['data'=>$review];} public function destroy(Request $r,Review $review){abort_unless($review->user_id===$r->user()->id,403);$review->delete();return response()->noContent();} }
